_MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
           "november", "december"]
_NAMED = re.compile(r"([A-Za-z]+) (\d{1,2}), (\d{4})")
_DMY = re.compile(r"(\d{2})/(\d{2})/(\d{4})")
_YMD = re.compile(r"(\d{4})\.(\d{2})\.(\d{2})")


