    s = text.strip(" ")
    match = _NAMED.fullmatch(s)
    if match:
        year, month, day = int(match.group(3)), _month(match.group(1)), int(match.group(2))
    elif _DMY.fullmatch(s):
        day, month, year = (int(g) for g in _DMY.fullmatch(s).groups())
